mapper.update:
 	update RSK_VALTBL_ASSET_SUB set
		FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
	where
		PTL_ID = #{ptlId}
		and (SUB_CODE = #{subCode} OR SUB_NAME in (SELECT SUB_NAME FROM RSK_VALTBL_ASSET_SUB WHERE SUB_CODE = #{subCode} AND PTL_ID = #{ptlId}))
		and FINPROD_ID is not null

		and FINPROD_ID != #{finprodId}

mapper.select:
SELECT distinct T1.PTL_ID ptlId, T1.SUB_CODE subCode, T1.SUB_NAME subName, T1.SUB_CLASS subClass, T1.ASSET_SOURCE assetSource, T1.FINPROD_ID finprodId, nvl(T2.FINPROD_MARKET_ID,T3.ASSET_CODE) finprodMarketId, nvl(T2.FINPROD_ABBR,T3.ASSET_NAME) finprodAbbr, T2.TRADE_MARKET tradeMarket FROM RSK_VALTBL_PRT_BOTASSET_MAP T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID left join RSK_ASSET_INFO T3 on T1.FINPROD_ID = T3.ASSET_CODE and T3.status in ('E', 'M') where not exists ( select r2.sub_code from RSK_VALTBL_PRT_BOTASSET_MAP r2 join RSK_VALTBL_SUBRELATION r3 ON r2.SUB_CODE LIKE concat(r3.int_subject,'%') where T1.PTL_ID = r2.PTL_ID and T1.SUB_CODE = r2.SUB_CODE )
and T1.FINPROD_ID is not null
and T1.PTL_ID = #{ptlId}

